WITH latest AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status, customer_id ORDER BY end_date DESC NULLS FIRST, id) AS latest_rank FROM subscriptions QUALIFY latest_rank = 1), joined AS (SELECT src.id, src.customer_id, src.plan, src.end_date, src.monthly_fee, src.status, b.city, b.email, b.name FROM latest src LEFT JOIN customers b ON src.customer_id = b.id WHERE b.city NOT IN ('London', 'Bangkok')), joined_subscriptions AS (SELECT s.*, b.email AS customer_email FROM joined s LEFT JOIN customers b ON s.customer_id <=> b.id), deduped AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id, status ORDER BY monthly_fee DESC NULLS FIRST, id) AS dedup_rank FROM joined_subscriptions) t WHERE dedup_rank = 1) SELECT id, customer_id, plan, end_date, monthly_fee, status, email, name, customer_email, CASE WHEN name RLIKE '^(Olivia Garcia|Emma Brown)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS name_zone FROM deduped;
